-- =====================================================================
-- Agentic SalesMan -- SECOND batch of 300 sample catalog rows (100
-- phone / 100 laptop / 100 headphone). Same schema as sample_data_300.sql
-- (the first batch); every name here is distinct from that file's names,
-- so it's safe to load both without name collisions in a single table.
--
-- Run this AFTER sample_data_300.sql (or on its own if your tables/
-- enrichment columns already exist -- the CREATE TABLE / ALTER TABLE
-- statements below are harmless no-ops in that case; delete any ALTER
-- line MySQL reports as a duplicate column and re-run the rest):
--
--   mysql -u <username> -p retail_shop < sample_data_300_batch2.sql
--
-- As with the first batch, `online_link` values are placeholder URLs --
-- replace with real product pages before this is customer-facing. After
-- loading, restart the backend (or delete WORKFLOW/chroma_db/) so
-- DATABASE/SQL_CONNECTOR.py's row-count sync re-embeds the new rows.
-- =====================================================================

CREATE TABLE IF NOT EXISTS phone (
    id                  INT AUTO_INCREMENT PRIMARY KEY,
    name                VARCHAR(255) NOT NULL,
    brand               VARCHAR(100) NOT NULL,
    price               INT NOT NULL,
    mrp                 INT NULL,
    processor           VARCHAR(100) NULL,
    ram                 VARCHAR(20) NULL,
    storage             VARCHAR(20) NULL,
    color               VARCHAR(50) NULL,
    units_available     INT NULL,
    rating              DECIMAL(2,1) NULL,
    online_link         VARCHAR(500) NULL,
    offline_availability VARCHAR(255) NULL
);

CREATE TABLE IF NOT EXISTS laptop (
    id                  INT AUTO_INCREMENT PRIMARY KEY,
    name                VARCHAR(255) NOT NULL,
    brand               VARCHAR(100) NOT NULL,
    price               INT NOT NULL,
    mrp                 INT NULL,
    processor           VARCHAR(100) NULL,
    ram                 VARCHAR(20) NULL,
    storage             VARCHAR(20) NULL,
    color               VARCHAR(50) NULL,
    units_available     INT NULL,
    rating              DECIMAL(2,1) NULL,
    online_link         VARCHAR(500) NULL,
    offline_availability VARCHAR(255) NULL
);

CREATE TABLE IF NOT EXISTS headphone (
    id                  INT AUTO_INCREMENT PRIMARY KEY,
    name                VARCHAR(255) NOT NULL,
    brand               VARCHAR(100) NOT NULL,
    price               INT NOT NULL,
    mrp                 INT NULL,
    type                VARCHAR(100) NULL,
    quality             VARCHAR(100) NULL,
    color               VARCHAR(50) NULL,
    units_available     INT NULL,
    rating              DECIMAL(2,1) NULL,
    online_link         VARCHAR(500) NULL,
    offline_availability VARCHAR(255) NULL
);

ALTER TABLE phone     ADD COLUMN mrp INT NULL, ADD COLUMN units_available INT NULL, ADD COLUMN rating DECIMAL(2,1) NULL, ADD COLUMN online_link VARCHAR(500) NULL, ADD COLUMN offline_availability VARCHAR(255) NULL;
ALTER TABLE laptop    ADD COLUMN mrp INT NULL, ADD COLUMN units_available INT NULL, ADD COLUMN rating DECIMAL(2,1) NULL, ADD COLUMN online_link VARCHAR(500) NULL, ADD COLUMN offline_availability VARCHAR(255) NULL;
ALTER TABLE headphone ADD COLUMN mrp INT NULL, ADD COLUMN units_available INT NULL, ADD COLUMN rating DECIMAL(2,1) NULL, ADD COLUMN online_link VARCHAR(500) NULL, ADD COLUMN offline_availability VARCHAR(255) NULL;

